lorawan.globals:
volatile uint64_t {{ id }}Bits = 0;
volatile uint8_t {{ id }}Len = 0;
volatile unsigned long {{ id }}Edge = 0;
void IRAM_ATTR {{ id }}D0Isr() { {{ id }}Bits = {{ id }}Bits << 1; {{ id }}Len++; {{ id }}Edge = millis(); }
void IRAM_ATTR {{ id }}D1Isr() { {{ id }}Bits = {{ id }}Bits << 1 | 1; {{ id }}Len++; {{ id }}Edge = millis(); }
uint32_t {{ id }}Last = 0;
uint16_t {{ id }}Count = 0;
unsigned long {{ id }}At = 0;

lorawan.loop:
if ({{ id }}Len && millis() - {{ id }}Edge > 25) {
  noInterrupts();
  uint64_t _v = {{ id }}Bits;
  uint8_t _n = {{ id }}Len;
  {{ id }}Bits = 0;
  {{ id }}Len = 0;
  interrupts();
  uint8_t _half = _n == 26 ? 13 : _n == 34 ? 17 : _n == 37 ? 19 : 0;
  if (_half && __builtin_popcountll(_v >> (_n - _half)) % 2 == 0
      && __builtin_popcountll(_v & ((1ULL << _half) - 1)) % 2 == 1) {
    {{ id }}Last = (uint32_t)(_v >> 1 & ((1ULL << (_n - 2)) - 1));
    {{ id }}Count++;
    {{ id }}At = millis();
  }
}

lorawan.setup:
pinMode({{ pins.D0 }}, INPUT_PULLUP);
pinMode({{ pins.D1 }}, INPUT_PULLUP);
attachInterrupt(digitalPinToInterrupt({{ pins.D0 }}), {{ id }}D0Isr, FALLING);
attachInterrupt(digitalPinToInterrupt({{ pins.D1 }}), {{ id }}D1Isr, FALLING);

